// PCA9685: servo pulses over I2C
#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>

Adafruit_PWMServoDriver pwm;   // the board at its default address, 0x40

void setup() {
  Serial.begin(9600);
  pwm.begin();          // wakes the chip (it powers up asleep, every output LOW)
  pwm.setPWMFreq(50);   // a 20 ms frame: prescale 121, 4096 ticks of 4.88 µs
  for (int ch = 0; ch < 3; ch++) pwm.writeMicroseconds(ch, 1500);   // 1500 µs = 307 ticks: every servo to 90°
  Serial.println("pca9685: 50 Hz, ch0-2 at 1500 us (307 ticks)");
}

void loop() {}   // nothing to do: the chip keeps sending the pulses by itself

// PCA9685: servo pulses over I2C
#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>

Adafruit_PWMServoDriver pwm;   // the board at its default address, 0x40

// one pose a second: where the cube is, down, grip, up, across, down, let go
const int BASE_DEG[8]     = {90, 45, 45, 45, 45, 135, 135, 135};
const int SHOULDER_DEG[8] = {90, 90, 48, 48, 120, 120, 48, 48};
const int GRIP_DEG[8]     = {90, 150, 150, 70, 70, 70, 70, 150};
int now[3] = {90, 90, 90};
bool mirrored = false;

void servoDeg(int ch, int deg) {   // 0-180° as 600-2400 µs, the servo libraries' range
  pwm.writeMicroseconds(ch, map(deg, 0, 180, 600, 2400));
}

void moveTo(int b, int s, int g) {   // every joint a degree at a time, 8 ms a step, so the arm does not fling the cube
  int goal[3] = {b, s, g};
  bool moving = true;
  while (moving) {
    moving = false;
    for (int j = 0; j < 3; j++) {
      if (now[j] != goal[j]) {
        now[j] += now[j] < goal[j] ? 1 : -1;
        servoDeg(j, now[j]);
        moving = true;
      }
    }
    delay(8);
  }
}

void setup() {
  Serial.begin(9600);
  pwm.begin();          // wakes the chip (it powers up asleep, every output LOW)
  pwm.setPWMFreq(50);   // a 20 ms frame: prescale 121, 4096 ticks of 4.88 µs
  for (int j = 0; j < 3; j++) servoDeg(j, 90);
  Serial.println("pick and place: 8 poses, 1 s each");
}

void loop() {
  for (int i = 0; i < 8; i++) {
    unsigned long start = millis();
    int b = mirrored ? 180 - BASE_DEG[i] : BASE_DEG[i];   // every second round runs mirrored, so the cube goes back again
    Serial.print("pose ");
    Serial.print(i + 1);
    Serial.print(": base ");
    Serial.print(b);
    Serial.print(" shoulder ");
    Serial.print(SHOULDER_DEG[i]);
    Serial.print(" grip ");
    Serial.println(GRIP_DEG[i]);
    moveTo(b, SHOULDER_DEG[i], GRIP_DEG[i]);
    while (millis() - start < 1000) {}
  }
  mirrored = !mirrored;
}

// I2C scanner: who answers on the bus?
#include <Wire.h>

void setup() {
  Wire.begin();
  Serial.begin(9600);
  Serial.println("I2C scanner");
}

void loop() {
  for (byte addr = 1; addr < 127; addr++) {
    Wire.beginTransmission(addr);
    if (Wire.endTransmission() == 0) {   // 0 = a device acknowledged its address
      Serial.print("I2C device found at address 0x");
      if (addr < 16) Serial.print('0');
      Serial.print(addr, HEX);
      Serial.println(" !");
    }
  }
  delay(2000);
}

// PCA9685: servo pulses over I2C
#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>

Adafruit_PWMServoDriver pwm;   // the board at its default address, 0x40

void servoDeg(int ch, int deg) {   // 0-180° as 600-2400 µs, the servo libraries' range
  pwm.writeMicroseconds(ch, map(deg, 0, 180, 600, 2400));
}

void setup() {
  Serial.begin(9600);
  pwm.begin();          // wakes the chip (it powers up asleep, every output LOW)
  pwm.setPWMFreq(50);   // a 20 ms frame: prescale 121, 4096 ticks of 4.88 µs
  servoDeg(1, 90);
  servoDeg(2, 90);
  Serial.println("sweep: base 0-180-0, 6 s a round trip");
}

void report(int deg) {
  if (deg % 60 == 0) {
    Serial.print("base ");
    Serial.print(deg);
    Serial.println(" deg");
  }
}

void loop() {
  for (int deg = 0; deg < 180; deg++) { servoDeg(0, deg); report(deg); delay(16); }   // one degree every 16 ms: 3 s each way
  for (int deg = 180; deg > 0; deg--) { servoDeg(0, deg); report(deg); delay(16); }
}
